import itertools

def imp(p,q):
    return (not p) or q

def eval_formula(num, A, B):
    if num==1:
        return (not (A and B)) == ((not A) or (not B))
    if num==2:
        return (not (A or B)) == ((not A) and (not B))
    if num==3:
        return imp(A,B) == imp(not B, not A)
    if num==4:
        return imp(A,B) == ((not A) or B)
    if num==5:
        return imp(not A, B) == (A or (not B))
    if num==6:
        return (not imp(A,B)) == (A and (not B))

for n in range(1,7):
    vals = [eval_formula(n,A,B) for A,B in itertools.product([True,False], repeat=2)]
    print(n, vals, all(vals))
